73	        /// <summary>
74	        /// 发送手机短信验证码
75	        /// </summary>
76	        /// <param name="model"></param>
77	        /// <returns></returns>
78	        [HttpPost]
79	        [Route("getValidateCode")]
80	        [AllowAnonymous]
81	        [ServiceFilter(typeof(ModelValidateFilterAttribute))]
82	        public async Task<BaseResult> GetValidateCodeAsync(SendMobileValidateCodeReqModel model)
83	        {
84	            // 手机号daymax ，maxinterval 校验
85	            var lastestTimeKey = string.Format(PHONE_CAPTCHA_GET_TIME, model.Phone);
86	
87	            var lastestTime = await _redisClient.StringGetAsync(lastestTimeKey);
88	
89	            if (!string.IsNullOrWhiteSpace(lastestTime))
90	            {
91	                return BaseResult.Fail(ErrCodeEnum.Create_Captcha_300802);
92	            }
93	
94	            var dayCount = await _redisClient.StringIncrementAsync(string.Format(PHONE_CAPTCHA_DAY_COUNT_KEY, model.Phone, DateTime.Now.ToString("yyyyMMdd")), expiry: TimeSpan.FromDays(1));
95	
96	            if (dayCount > _options.Captcha.DayMaxGenTimes)
97	            {
98	                return BaseResult.Fail(ErrCodeEnum.Create_Captcha_300801);
99	            }
100	
101	            var setRet = await _redisClient.StringSetAsync(lastestTimeKey, DateTime.Now.ToUnixTimeStamp().ToString(), TimeSpan.FromSeconds(_options.Captcha.MaxGenInterval));
102	
103	            if (!setRet)
104	            {
105	                return BaseResult.Fail(ErrCodeEnum.Err, "值设置异常");
106	            }
107	
108	            // 如果是登录业务，需要校验手机号是否存在系统中
109	            if (model.VerifyType == VaidateCodeReqType.Login)
110	            {
111	                var checkLoginPhone = await _userService.CheckLoginPhoneAsync(model.Phone);
112	
113	                if (!checkLoginPhone.IsSuccess())
114	                {
115	                    return BaseResult.Fail(checkLoginPhone);
116	                }
117	            }
118	
119	            // 如果是校验业务，需要校验核验的供应商是否存在系统中
120	            if (model.VerifyType == VaidateCodeReqType.OrgAuth)
121	            {
122	                if (model.Param.Length < 1 || string.IsNullOrWhiteSpace(model.Param[0]) || string.IsNullOrWhiteSpace(model.Param[0].Trim()))
123	                {
124	                    return BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300901);
125	                }
126	
127	                var supplierInfo = await _orgService.GetSupplierInfoByCertNoAsync(model.Param[0].Trim());
128	
129	                if (supplierInfo == null)
130	                {
131	                    return BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300902);
132	                }
133	            }
134	
135	            if (model.VerifyType == VaidateCodeReqType.ChangePhone)
136	            {
137	                if (model.Param.Length < 3 || string.IsNullOrWhiteSpace(model.Param[0]) || string.IsNullOrWhiteSpace(model.Param[1]) || string.IsNullOrWhiteSpace(model.Param[2]))
138	                {
139	                    return BaseResult.Fail(ErrCodeEnum.ParametersInvalid, "用户名、身份证号、原手机号信息不全");
140	                }
141	                var ret = await _userService.CheckChangePhone(model.Param[0], model.Param[1], model.Param[2]);
142	                if (!ret.IsSuccess())
143	                {
144	                    return BaseResult.Fail(ErrCodeEnum.Check_Change_Phone_232201);
145	                }
146	            }
147	
148	            //生成验证码并发送
149	
150	            var captchaRet = await _captchaService.CreateCaptchaAsync(model.Phone);
151	
152	            if (captchaRet.Item1 != ErrCodeEnum.Success)
153	            {
154	                return BaseResult.Fail(captchaRet.Item1, captchaRet.Item2);
155	            }
156	
157	            var msg = string.Format(_options.Captcha.CaptchaTemplate, captchaRet.Item2);
158	
159	            var sendMsg = await _captchaService.DsmSenVerifyCode(model.Phone, msg);
160	
161	            return sendMsg
162	                ? BaseResult.Success
163	                : BaseResult.Fail(ErrCodeEnum.Send_Mobile_Validate_Code_300903);
164	
165	        }
