26	        /// <summary>
27	        /// PBEWithMD5AndDES
28	        /// </summary>
29	        [Test]
30	        public void PBEWithMD5AndDES()
31	        {
32	            string SALT = "63293188";
33	            int ITERATION_COUNT = 1000;
34	            string plaintext = "345465434676573324";
35	            var password = "Cessd_sdfa";
36	
37	            byte[] saltBytes = Encoding.ASCII.GetBytes(SALT);
38	            byte[] passwordBytes = Encoding.ASCII.GetBytes(password);
39	
40	            // 使用精确的Java PBE密钥派生算法
41	            byte[] derivedBytes = PBEKeyDerivation(passwordBytes, saltBytes, ITERATION_COUNT);
42	
43	            // 前8字节作为DES密钥，后8字节作为IV
44	            byte[] key = new byte[8];
45	            byte[] iv = new byte[8];
46	            Array.Copy(derivedBytes, 0, key, 0, 8);
47	            Array.Copy(derivedBytes, 8, iv, 0, 8);
48	
49	            using (var des = DES.Create())
50	            {
51	                des.Key = key;
52	                des.IV = iv;
53	                des.Mode = CipherMode.CBC;
54	                des.Padding = PaddingMode.PKCS7;
55	
56	                using (var encryptor = des.CreateEncryptor())
57	                using (var ms = new System.IO.MemoryStream())
58	                using (var cs = new CryptoStream(ms, encryptor, CryptoStreamMode.Write))
59	                {
60	                    byte[] plaintextBytes = Encoding.ASCII.GetBytes(plaintext);
61	                    cs.Write(plaintextBytes, 0, plaintextBytes.Length);
62	                    cs.FlushFinalBlock();
63	
64	                    byte[] encipheredData = ms.ToArray();
65	                    var a= BytesToHexString(encipheredData);
66	                }
67	            }
68	        }
69	
70	        private byte[] PBEKeyDerivation(byte[] password, byte[] salt, int iterationCount)
71	        {
72	            // Java PBEWithMD5AndDES的精确密钥派生算法
73	            // 生成20字节（8字节密钥 + 8字节IV + 4字节填充）
74	            int keyLength = 20;
75	            byte[] finalKey = new byte[keyLength];
76	
77	            int offset = 0;
78	            byte[] temp = new byte[0];
79	
80	            while (offset < keyLength)
81	            {
82	                // 每次迭代使用MD5
83	                using (var md5 = MD5.Create())
84	                {
85	                    byte[] toHash = new byte[temp.Length + password.Length + salt.Length];
86	
87	                    // Java的顺序：先password，后salt，最后previous hash
88	                    Array.Copy(password, 0, toHash, 0, password.Length);
89	                    Array.Copy(salt, 0, toHash, password.Length, salt.Length);
90	                    if (temp.Length > 0)
91	                    {
92	                        Array.Copy(temp, 0, toHash, password.Length + salt.Length, temp.Length);
93	                    }
94	
95	                    temp = md5.ComputeHash(toHash);
96	                }
97	
98	                // 迭代指定次数
99	                for (int i = 1; i < iterationCount; i++)
100	                {
101	                    using (var md5 = MD5.Create())
102	                    {
103	                        temp = md5.ComputeHash(temp);
104	                    }
105	                }
106	
107	                // 复制到最终密钥
