12	    {
13	        private ILogger _logger;
14	        /// <summary>
15	        /// 
16	        /// </summary>
17	        public ModelValidateFilterAttribute(ILoggerProvider loggerProvider)
18	        {
19	            _logger = loggerProvider.CreateLogger(nameof(ModelValidateFilterAttribute));
20	        }
21	
22	        /// <summary>
23	        /// 
24	        /// </summary>
25	        /// <param name="context"></param>
26	        public override void OnActionExecuting(ActionExecutingContext context)
27	        {
28	            var modelState = context.ModelState;
29	
30	            _logger.LogInformation($"参数拦截内容：{modelState.ToJson()}");
31	
32	            if (!modelState.IsValid)
33	            {
34	                _logger.LogInformation($"拦截结果：{modelState.Values.ToJson()}");
35	
36	                var msg = modelState.Values.FirstOrDefault(q => q.Errors.Count > 0)?.Errors.FirstOrDefault()?.ErrorMessage ?? "Model Validate Fail";
37	
38	                context.Result = new ContentResult
39	                {
40	                    Content = BaseResult.Fail(ErrCodeEnum.ParametersInvalid, msg).ToJson(),
41	                    ContentType = ContentTypes.JSON,
42	                };
43	            }
44	        }
45	    }
46	}

